type LogoProps = { className?: string };

function BrandMark({
  bg,
  path,
  fg = "#fff",
  className,
}: {
  bg: string;
  path: string;
  fg?: string;
  className?: string;
}) {
  return (
    <svg viewBox="0 0 24 24" className={className} aria-hidden>
      <rect width="24" height="24" rx="5" fill={bg} />
      <g transform="translate(4 4) scale(0.6667)">
        <path fill={fg} d={path} />
      </g>
    </svg>
  );
}

