export type PublishBrandIconId =
  | CmsPlatformId
  | EspPlatformId
  | ExportDestinationId
  | SocialIntegrationId
  | "instagram"
  | "facebook";

const LOGOS: Partial<Record<PublishBrandIconId, ComponentType<LogoProps>>> = {
  wordpress: WordpressLogo,
  ghost: GhostLogo,
  shopify: ShopifyLogo,
  webflow: WebflowLogo,
  notion: NotionLogo,
  drupal: DrupalLogo,
  joomla: JoomlaLogo,
  webhook: WebhookLogo,
  contentful: ContentfulLogo,
  sanity: SanityLogo,
  strapi: StrapiLogo,
  typo3: Typo3Logo,
  wix: WixLogo,
  framer: FramerLogo,
  squarespace: SquarespaceLogo,
  hubspot: HubspotLogo,
  beehiiv: BeehiivLogo,
  convertkit: ConvertKitLogo,
  mailchimp: MailchimpLogo,
  medium: MediumLogo,
  substack: SubstackLogo,
  linkedin: LinkedinLogo,
  twitter: XLogo,
  meta: MetaLogo,
  bluesky: BlueskyLogo,
  mastodon: MastodonLogo,
  instagram: InstagramLogo,
  facebook: FacebookLogo,
};

export function PublishBrandIcon({
  id,
  className,
}: {
  id: PublishBrandIconId;
  className?: string;
}) {
  const Logo = LOGOS[id];
  if (!Logo) return null;
  return <Logo className={cn("h-8 w-8 shrink-0", className)} />;
}
